function escapeXml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

/**
 * Automatically extracts large code blocks (>6 lines) from the model's text response,
 * materializes them into standalone files in ./workspace/, and replaces them in the
 * chat response with sleek, compact workspace references and preview pills.
 */
export function isolateCodeBlocksToWorkspace(response = '', query = '', workspaceDir) {
  if (!response || typeof response !== 'string')
    return { cleanResponse: response, isolatedArtifacts: [] };
  if (!workspaceDir) return { cleanResponse: response, isolatedArtifacts: [] };

  try {
    if (!fs.existsSync(workspaceDir)) {
      fs.mkdirSync(workspaceDir, { recursive: true });
    }
  } catch (_) {}

  const isolatedArtifacts = [];
  const qSlug =
    (query || 'file')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .slice(0, 24)
      .replace(/^_+|_+$/g, '') || 'script';
  const timestamp = Date.now().toString(36);
  let fileIndex = 1;

  // Ensure any trailing unclosed code block is cleanly terminated before matching
  let normalizedResponse = response;
  const tickCount = (normalizedResponse.match(/```/g) || []).length;
  if (tickCount % 2 !== 0) {
    normalizedResponse += '\n```\n';
  }

  // Match markdown fenced code blocks: ```[lang]?\n[code]\n```
  const codeBlockRegex = /```([a-zA-Z0-9_-]*)\s*([\r\n][\s\S]*?)```/g;

  const cleanResponse = normalizedResponse.replace(codeBlockRegex, (match, lang, code) => {
    let rawCode = code.trim();
    const lines = rawCode.split('\n');

    // Only isolate blocks that are significant (>6 lines or >250 chars)
    if (lines.length <= 6 && rawCode.length < 250) {
      return match; // Keep small inline snippets in chat
    }

    const language = (lang || '').toLowerCase().trim();
    let ext = 'txt';
    if (['javascript', 'js', 'jsx'].includes(language)) {
      ext = 'js';
    } else if (['typescript', 'ts', 'tsx'].includes(language)) {
      ext = 'ts';
    } else if (['python', 'py'].includes(language)) {
      ext = 'py';
    } else if (['html', 'htm'].includes(language)) {
      ext = 'html';
    } else if (['css', 'scss'].includes(language)) {
      ext = 'css';
    } else if (['json'].includes(language)) {
      ext = 'json';
    } else if (['glsl', 'frag', 'vert', 'shader'].includes(language)) {
      ext = 'glsl';
    } else if (['sql'].includes(language)) {
      ext = 'sql';
    } else if (['bash', 'sh', 'shell', 'powershell', 'ps1'].includes(language)) {
      ext = 'ps1';
    } else if (['c', 'cpp', 'h', 'hpp', 'cc'].includes(language)) {
      ext = 'cpp';
    } else if (['rust', 'rs'].includes(language)) {
      ext = 'rs';
    } else if (['yaml', 'yml'].includes(language)) {
      ext = 'yaml';
    } else if (['md', 'markdown'].includes(language)) {
      ext = 'md';
    }

    // Only treat as HTML if the code block contains actual HTML markup or doctype
    if (ext === 'html' || /<!DOCTYPE\s+html|<html[\s>]/i.test(rawCode)) {
      ext = 'html';
    }

    // 1. Try to detect filename from first 3 lines comment (e.g. // LRUCache.ts, # rate_limiter.py, <!-- index.html -->)
    let explicitFilename = null;
    for (let i = 0; i < Math.min(lines.length, 3); i++) {
      const line = lines[i].trim();
      const nameMatch = line.match(
        /^(?:\/\/|#|\/\*|<!--)\s*(?:file(?:name)?:\s*|\.\/workspace\/|workspace\/|\.\/)?([a-zA-Z0-9_.-]+\.[a-zA-Z0-9]+)/i,
      );
      if (nameMatch) {
        explicitFilename = nameMatch[1];
        break;
      }
    }

    // 2. Try class, interface, or struct definition
    if (!explicitFilename) {
      for (let i = 0; i < Math.min(lines.length, 10); i++) {
        const line = lines[i].trim();
        const classMatch = line.match(
          /(?:export\s+)?(?:default\s+)?(?:class|interface|struct)\s+([A-Za-z0-9_]+)/,
        );
        if (classMatch) {
          explicitFilename = `${classMatch[1]}.${ext}`;
          break;
        }
        const funcMatch = line.match(
          /(?:export\s+)?(?:async\s+)?(?:function|def)\s+([a-zA-Z0-9_]+)/,
        );
        if (funcMatch && funcMatch[1] !== 'main' && funcMatch[1] !== 'test') {
          explicitFilename = `${funcMatch[1]}.${ext}`;
          break;
        }
      }
    }

    // 3. Fallback to clean semantic noun from query
    if (!explicitFilename) {
      const cleanNoun = (query || '')
        .toLowerCase()
        .replace(
          /^(?:write|create|implement|build|develop|generate|make|show|give\s+me)\s+(?:an?|the)?\s*/i,
          '',
        )
        .replace(/\s+(?:in|using|with|and|for)\s+.*$/i, '')
        .trim()
        .replace(/[^a-z0-9]+/g, '_')
        .slice(0, 24)
        .replace(/^_+|_+$/g, '');
      if (cleanNoun && cleanNoun.length > 2) {
        explicitFilename =
          fileIndex === 1 ? `${cleanNoun}.${ext}` : `${cleanNoun}_${fileIndex}.${ext}`;
      } else {
        explicitFilename = fileIndex === 1 ? `solution.${ext}` : `module_${fileIndex}.${ext}`;
      }
      fileIndex++;
    }

    let processedCode = rawCode;

    // Intelligent HTML Validation & Autonomous Harness Synthesis
    if (ext === 'html') {
      const hasHtmlTag = /<html/i.test(processedCode) || /<!DOCTYPE/i.test(processedCode);
      const isPureJs =
        /^(?:import\s|const\s|let\s|var\s|function\s|\/\*|\/\/)/m.test(processedCode) &&
        !/<[a-z][\s\S]*>/i.test(processedCode);

      if (isPureJs || !hasHtmlTag) {
        processedCode = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>${escapeXml(query || 'Visual Simulation')}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <link rel="icon" href="data:,">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 100%; height: 100%; overflow: hidden; background: #06080D; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #FFF; }
    canvas { width: 100% !important; height: 100% !important; display: block; position: absolute; top: 0; left: 0; }
  </style>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/PointerLockControls.js"></script>
</head>
<body>
  <canvas id="game-canvas"></canvas>
  <script>
${processedCode}
  </script>
</body>
</html>`;
      } else {
        // Repair truncated HTML tags if cut off
        if (processedCode.includes('<script') && !processedCode.includes('</script>')) {
          processedCode += '\n  </script>\n';
        }
        if (processedCode.includes('<body') && !processedCode.includes('</body>')) {
          processedCode += '</body>\n';
        }
        if (processedCode.includes('<html') && !processedCode.includes('</html>')) {
          processedCode += '</html>\n';
        }
      }

      // Clean broken relative links that 404 in workspace (e.g. <link rel="stylesheet" href="style.css">)
      processedCode = processedCode.replace(
        /<link\s+[^>]*href=["'](?:style\.css|styles\.css)["'][^>]*>/gi,
        (linkTag) => {
          const stylePath = path.join(workspaceDir, 'style.css');
          return fs.existsSync(stylePath) ? linkTag : '<!-- [removed missing local stylesheet] -->';
        },
      );
    }

    const filename = explicitFilename;
    const filePath = path.join(workspaceDir, filename);

    try {
      fs.writeFileSync(filePath, processedCode, 'utf8');

      const sizeBytes = Buffer.byteLength(processedCode, 'utf8');
      const sizeKb = (sizeBytes / 1024).toFixed(1);
      const processedLines = processedCode.split('\n');

      isolatedArtifacts.push({
        id: `art-isolated-${fileIndex}-${Date.now().toString(36)}`,
        name: filename,
        filename: filename,
        title: ext === 'html' ? `🎮 ${filename}` : `📄 ${filename}`,
        type: ext,
        badge: 'Isolated Workspace File',
        url: `/workspace/${filename}`,
        size: sizeBytes,
        description: `Autonomous code extract: ${processedLines.length} lines (${sizeKb} KB) in ./workspace/${filename}`,
      });

      // Deliver clean, untruncated markdown code block without raw quote clutter
      return `\n\`\`\`${language}\n${rawCode}\n\`\`\`\n`;
    } catch (err) {
      console.warn('[IntelligentUIBundleEngine] Could not isolate code file:', err.message);
      return match;
    }
  });

  return { cleanResponse, isolatedArtifacts };
}
